import{z as c,x as B,o as l,c as p,q as t,j as n,D as s,d as r,s as o,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"gVisor","description":"","frontmatter":{"title":"gVisor","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gvisor.md","filePath":"cs/gvisor.md","lastUpdated":1791413859000}'),A={name:"cs/gvisor.md"};function d(u,a,m,S,g,f){const i=B("Mermaid");return l(),p("div",null,[a[2]||(a[2]=t('<h1 id="gvisor" tabindex="-1">gVisor <a class="header-anchor" href="#gvisor" aria-label="Permalink to &quot;gVisor&quot;">​</a></h1><div class="epigraph"><p>gVisor 的 Sentry 在用户态实现 Linux 系统调用：应用 ptrace 或 systrap 进入 Sentry，宿主内核看见的是 Sentry 的调用，而不是应用的。</p><footer>—— 据 gVisor 文档；[seccomp]/ptrace 与 [FUSE](/cs/fuse) 为用户态代内核对照</footer></div><p><a href="/cs/oci-image-layers">上一课</a>留下的缺口接到本课。 <a href="/cs/container-runtime">runc</a> 把 syscall 直接给宿主。<a href="/cs/kvm-qemu">KVM</a> 是另一极端。缺口是 <strong>应用内核在用户态</strong>：gVisor。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Sentry 实现 VFS、net、mm 子集。Gofer 代文件。缺口：兼容性（不是每个 ioctl）；性能税；与 <a href="/cs/lsm-selinux">LSM</a> 宿主仍包一层。本课不把 Sentry 内部写成 Go 课。</p><p><span class="marginnote">术语翻译：Sentry 就是一个跑在普通用户进程里的「迷你 Linux 内核」——用 Go 把 VFS、网络栈、内存管理这些内核子系统重写了一遍，专门接应用发来的系统调用。</span></p><p><span class="marginnote">直觉类比：Sentry 像一位全职翻译中介。应用只会说「Linux 方言」（300 多个 syscall），中介把它翻译成宿主内核听的少数几句「基础用语」；宿主从头到尾只见中介，见不到应用本人——应用带进来的恶意请求也就够不着宿主内核。</span></p><p><span class="marginnote">平台：ptrace 慢，KVM 平台用硬件隔离跑 Sentry。对象是缩减内核攻击面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用 syscall → 陷入 Sentry → Sentry 用有限宿主 syscall 完成。对照 <a href="/cs/fuse">FUSE</a>：文件可走 gofer。对照 [seccomp]：过滤 vs 重新实现。对照 <a href="/cs/unikernel">unikernel</a> 后课：一个截 syscall，一个无 syscall。</p>',10)),(l(),n(E,null,{default:s(()=>[o(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%20syscall%22%5D%20--%3E%20SEN%5B%22Sentry%20%E7%94%A8%E6%88%B7%E6%80%81%E5%86%85%E6%A0%B8%22%5D%0A%20%20SEN%20--%3E%20HOST%5B%22%E5%B0%91%E9%87%8F%E5%AE%BF%E4%B8%BB%E8%B0%83%E7%94%A8%22%5D%0A%20%20SEN%20--%3E%20GOF%5B%22Gofer%20%E6%96%87%E4%BB%B6%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("gVisor 把 Linux ABI 的实现从宿主内核挪到用户进程，使内核漏洞对应用更远。代价是慢与不全。不要写成「比 VM 安全」的绝对句。与 "),e("a",{href:"/cs/ebpf-observability"},"eBPF"),r("：观测要看 Sentry 不是宿主进程树直觉。")],-1)),a[5]||(a[5]=e("p",null,"不支持的 syscall 会 ENOSYS，应用崩。",-1)),(l(),n(E,null,{default:s(()=>[o(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20COMPARE%5B%22syscall%20%E8%B7%AF%E5%BE%84%E5%AF%B9%E6%AF%94%22%5D%0A%20%20%20%20R%5B%22runc%EF%BC%9A%E5%BA%94%E7%94%A8%22%5D%20--%3E%7Csyscall%20%E7%9B%B4%E6%8E%A5%E8%BF%9B%E5%85%A5%7C%20HK%5B%22%E5%AE%BF%E4%B8%BB%E5%86%85%E6%A0%B8%EF%BC%88%E6%94%BB%E5%87%BB%E9%9D%A2%E5%85%A8%E6%9A%B4%E9%9C%B2%EF%BC%89%22%5D%0A%20%20%20%20G%5B%22gVisor%EF%BC%9A%E5%BA%94%E7%94%A8%22%5D%20--%3E%20SEN2%5B%22Sentry%EF%BC%88%E7%94%A8%E6%88%B7%E6%80%81%E5%AE%9E%E7%8E%B0%EF%BC%89%22%5D%20--%3E%7C%E5%B0%91%E9%87%8F%E8%B0%83%E7%94%A8%7C%20HK%0A%20%20%20%20V%5B%22VM%EF%BC%9A%E5%BA%94%E7%94%A8%22%5D%20--%3E%20GUEST%5B%22%E5%AE%A2%E6%88%B7%E5%86%85%E6%A0%B8%22%5D%20--%3E%7C%E8%99%9A%E6%8B%9F%E5%8C%96%E5%87%BA%E5%8F%A3%7C%20HV%5B%22VMM%20%2F%20%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20end%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">常见误区：gVisor 不是让容器跑得更快的加速器，而是一张「性能税换安全距离」的价目表——syscall 越密集（高频小文件、高频网络）税越重；syscall 稀疏的作业付得很少。</span></p><p>实现上：Sentry 的网络栈自己实现，和宿主 conntrack 不是一张表。ptrace 平台每个 syscall 两次陷入，KVM 平台用硬件隔离跑 Sentry。不支持的 ioctl 直接失败。 读法上只引用<a href="/cs/oci-image-layers">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>gVisor</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有平台后端。不保证 GPU。下一课微型 VM：Firecracker。</p><p>版本字段会变，课序钉的是机制对象「gVisor」，不是某一主线内核的结构体名。 后课默认：可用用户态内核截 syscall。专用微型 VMM，下一课 Firecracker。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>gVisor 用 Sentry 在用户态实现 Linux ABI。</li><li>减宿主内核暴露，付性能与兼容。</li><li>Firecracker 是下一课。</li><li>出处：gVisor 文档；OCI；KVM 平台说明。</li></ul>',9))])}const y=c(A,[["render",d]]);export{h as __pageData,y as default};
